func Close() error {
	log.Info("Closing Database")
	return Db().Close()
}

func EnsureLatestVersion() {
	db := Db()

	// Disable foreign_keys to allow re-creating tables in migrations
	_, err := db.Exec("PRAGMA foreign_keys=off")
